public class Main {
    public static void main(String[] args) {
        InputStream inStream = System.in;
        PrintWriter outStream = new PrintWriter(System.out);
        InputReader reader = new InputReader(inStream);
        processShuffles(reader, outStream);
        outStream.close();
    }

    static void processShuffles(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        NumberTheory.Mod998 mod = new NumberTheory.Mod998();
        mod.fInv(n + m);

        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = mod.mult(p, n - i, mod.smallInv(n + m - i));
            phaseSize = mod.add(phaseSize, p);
        }

        long totalAnswer = 0;
        for (int k = 1; k <= n; k++) {
            long sign = mod.paritySign(k + 1);
            long numPhases = mod.div(m + k, k);
            long term = mod.mult(sign, mod.ncr(n, k), numPhases, phaseSize);
            totalAnswer = mod.add(totalAnswer, term);
        }

        out.println(totalAnswer);
    }
}

class InputReader {
    BufferedReader br;
    StringTokenizer st;

    public InputReader(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
        st = null;
    }

    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}
