#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998;
    long long inv_n_plus_m;

    long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long mult(long long a, long long b, long long c) {
        return mult(mult(a, b), c);
    }

    long long par_sign(long long k) {
        return (k % 2 == 0) ? 1 : -1;
    }

    long long pow_mod(long long base, long long exp) {
        long long result = 1;
        long long cur = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = (result * cur) % MOD;
            cur = (cur * cur) % MOD;
            exp >>= 1;
        }
        return result;
    }

    long long inv(long long a) {
        // Fermat's little theorem for prime MOD
        return pow_mod(a, MOD - 2);
    }

    void fInv(long long n) {
        inv_n_plus_m = inv(n);
    }

    long long ncr(long long n, long long r) {
        if (r > n || r < 0) return 0;
        long long numerator = 1;
        long long denominator = 1;
        for (long long i = 1; i <= r; ++i) {
            numerator = mult(numerator, n - i + 1);
            denominator = mult(denominator, i);
        }
        return mult(numerator, inv(denominator));
    }

    long long div(long long a, long long b) {
        return mult(a, inv(b));
    }

    long long smallInv(long long a) {
        return inv(a);
    }

    long long paritySign(long long k) {
        return (k % 2 == 0) ? 1 : -1;
    }

    long long mult(long long a, long long b, long long c, long long d) {
        long long res = mult(a, b);
        res = mult(res, c);
        res = mult(res, d);
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    Mod998 mod;
    mod.fInv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, n - i, mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long totalAnswer = 0;
    for (int k = 1; k <= n; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = mod.div(m + k, k);
        long long term = mod.mult(sign, mod.ncr(n, k), numPhases, phaseSize);
        totalAnswer = mod.add(totalAnswer, term);
    }

    cout << totalAnswer << "\n";

    return 0;
}
